groups = []
def group(slug, title, intro, caution, refs, rows):
    items = []
    for line in rows.strip().splitlines():
        name, loop, use, tech = [part.strip() for part in line.split('|')]
        items.append({'id': f'cam-{sum(len(g["items"]) for g in groups)+len(items)+1:03}', 'name': name, 'interaction': loop, 'application': use, 'tech': tech.split(',')})
    assert len(items) == 8, (title, len(items))
    groups.append({'id': slug, 'title': title, 'intro': intro, 'caution': caution, 'sources': refs.split(','), 'items': items})

